import{_ as t,o as a,c as n,a4 as e}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"10. AI 协作：跨端代码最容易想当然","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"模板一：让它先认版本，再写代码","slug":"模板一-让它先认版本-再写代码","link":"#模板一-让它先认版本-再写代码","children":[]},{"level":3,"title":"模板二：让它审查跨端兼容性","slug":"模板二-让它审查跨端兼容性","link":"#模板二-让它审查跨端兼容性","children":[]},{"level":3,"title":"模板三：给它两端的行为，让它定位差异","slug":"模板三-给它两端的行为-让它定位差异","link":"#模板三-给它两端的行为-让它定位差异","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"用已经改名的组件库","slug":"用已经改名的组件库","link":"#用已经改名的组件库","children":[]},{"level":3,"title":"把 Web 的 API 写进来","slug":"把-web-的-api-写进来","link":"#把-web-的-api-写进来","children":[]},{"level":3,"title":"用 vue-router 的写法做跳转","slug":"用-vue-router-的写法做跳转","link":"#用-vue-router-的写法做跳转","children":[]},{"level":3,"title":"生命周期钩子从 vue 导入","slug":"生命周期钩子从-vue-导入","link":"#生命周期钩子从-vue-导入","children":[]},{"level":3,"title":"新加了页面但不改 pages.json","slug":"新加了页面但不改-pages-json","link":"#新加了页面但不改-pages-json","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[]}],"relativePath":"mobile/10-ai-collaboration.md","filePath":"mobile/10-ai-collaboration.md","lastUpdated":1789500881000}'),i={name:"mobile/10-ai-collaboration.md"};function o(d,s,p,l,r,c){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_10-ai-协作-跨端代码最容易想当然" tabindex="-1">10. AI 协作：跨端代码最容易想当然 <a class="header-anchor" href="#_10-ai-协作-跨端代码最容易想当然" aria-label="Permalink to &quot;10. AI 协作：跨端代码最容易想当然&quot;">​</a></h1><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>先给判断标准：<strong>能靠“大量相似代码”解决的活可以交给 AI，需要判断“这个 API 在端上存不存在”的活不能。</strong></p><p>写用户端时，AI 的处境和管理端不一样。管理端是纯 Web 环境，AI 见过的代码量极大；<strong>用户端多了一层平台约束，而 AI 不知道你跑在哪一端</strong> —— 它默认按浏览器的规则给你写代码，出来能用才怪。</p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>写页面骨架（卡片、列表、表单布局）</td><td>能</td><td>结构相似，样式写法通用</td></tr><tr><td>写状态判断的 <code>computed</code></td><td>能</td><td>纯逻辑，不依赖平台</td></tr><tr><td>写工具函数（日期格式化、字典映射）</td><td>能</td><td>和管理端是同一件事</td></tr><tr><td>解释一个陌生的报错</td><td>能，但要核实</td><td>它可能给出平台不对的解法</td></tr><tr><td>推荐组件库与用法</td><td><strong>不能直接信</strong></td><td>组件库换过名字，它的知识可能停在上一个版本</td></tr><tr><td>写请求封装</td><td>能，但要审</td><td>它习惯用 <code>axios</code>，会写成浏览器那套</td></tr><tr><td>写页面跳转</td><td><strong>不能直接信</strong></td><td>它习惯 <code>vue-router</code> 的写法</td></tr><tr><td>决定页面结构（哪些页、怎么分）</td><td>不能</td><td>这是设计判断</td></tr><tr><td>判断某段代码能否跨端</td><td>不能</td><td><strong>它给不出可信答案，只能你自己在两个端跑一遍</strong></td></tr></tbody></table><p><strong>最后一行是这一篇的核心。</strong> 前面 9 篇里反复出现的“两个端都要跑一遍”，对 AI 生成的东西更加必要 —— 它写出来的代码通常在 H5 端能跑，在小程序端才暴露问题。</p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="模板一-让它先认版本-再写代码" tabindex="-1">模板一：让它先认版本，再写代码 <a class="header-anchor" href="#模板一-让它先认版本-再写代码" aria-label="Permalink to &quot;模板一：让它先认版本，再写代码&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要在 uni-app 项目里加一个活动列表页。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>动手之前先确认这几件事，不要凭记忆假设：</span></span>
<span class="line"><span>1. 这是 uni-app 的 Vue 3 + Vite 版本，不是 uni-app x</span></span>
<span class="line"><span>2. UI 组件库是 @wot-ui/ui（注意不是旧名 wot-design-uni），</span></span>
<span class="line"><span>   组件通过 pages.json 的 easycom 自动引入，前缀是 wd-</span></span>
<span class="line"><span>3. 项目已经有一个封装好的请求层，用法是 http.get(url, params)，</span></span>
<span class="line"><span>   路径不带 /api 前缀，返回值已经是业务 data，错误对象上带 code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>确认之后按这些约束写：</span></span>
<span class="line"><span>- 用 script setup，生命周期钩子从 @dcloudio/uni-app 导入</span></span>
<span class="line"><span>- 不要用 window、document、localStorage、axios</span></span>
<span class="line"><span>- 样式用 rpx，细线用 px</span></span>
<span class="line"><span>- 需要跨端差异的地方用条件编译，注释掉不需要的那一端</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出就是这一个 vue 文件的完整代码，不要解释。</span></span></code></pre></div><p><strong>为什么这么写：</strong> 三条“先确认”对应三类它最容易错的地方 —— 框架版本、组件库名称、项目已有的约定。<strong>尤其第二条</strong>，组件库换过名字，如果不点名，它很可能给你写出 <code>wot-design-uni</code> 的引入路径。</p><p>最后一句“不要解释”也是有意的：<strong>解释会占掉一半输出，而你要的是代码。</strong> 需要解释时单独再问。</p><h3 id="模板二-让它审查跨端兼容性" tabindex="-1">模板二：让它审查跨端兼容性 <a class="header-anchor" href="#模板二-让它审查跨端兼容性" aria-label="Permalink to &quot;模板二：让它审查跨端兼容性&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我写的 uni-app 页面代码：</span></span>
<span class="line"><span>（贴代码）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我逐个标出这些写法在微信小程序端会发生什么：</span></span>
<span class="line"><span>- 哪些 API 在小程序里不存在</span></span>
<span class="line"><span>- 哪些 CSS 属性小程序不支持或表现不同</span></span>
<span class="line"><span>- 哪些地方需要条件编译</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按“行号 → 问题 → 建议改法”的表格输出。</span></span>
<span class="line"><span>不确定的地方标出来，不要猜。</span></span></code></pre></div><p><strong>为什么这么写：</strong> 直接让它“检查代码质量”，它会给你一堆命名建议；<strong>指定“跨端兼容性”这个角度</strong>，它才会往平台差异上想。最后一句“不确定的标出来”很重要 —— 跨端的具体支持情况它常常拿不准，<strong>宁可让它承认不确定，也别让它编一个看起来合理的答案。</strong></p><h3 id="模板三-给它两端的行为-让它定位差异" tabindex="-1">模板三：给它两端的行为，让它定位差异 <a class="header-anchor" href="#模板三-给它两端的行为-让它定位差异" aria-label="Permalink to &quot;模板三：给它两端的行为，让它定位差异&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一份代码，H5 端正常，微信小程序端出现下面的现象：</span></span>
<span class="line"><span>（贴小程序端的报错或截图描述）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>相关代码是：</span></span>
<span class="line"><span>（贴代码）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可能是哪几类原因？按可能性从高到低列出来，每类给我一个验证办法。</span></span>
<span class="line"><span>不要直接给修改后的完整代码，先让我确认是哪一类。</span></span></code></pre></div><p><strong>为什么这么写：</strong> 只报一个端的现象，AI 倾向于猜一个原因然后大改一通。<strong>要求“先给分类和验证办法”</strong>，你就有了自己判断的机会 —— <strong>跨端问题里，猜错方向比改错代码浪费更多时间。</strong></p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="用已经改名的组件库" tabindex="-1">用已经改名的组件库 <a class="header-anchor" href="#用已经改名的组件库" aria-label="Permalink to &quot;用已经改名的组件库&quot;">​</a></h3><p><strong>现象：</strong> AI 给你的代码里出现 <code>pnpm add wot-design-uni</code> 或者 <code>&quot;^wd-(.*)&quot;: &quot;wot-design-uni/components/wd-$1/wd-$1.vue&quot;</code>。</p><p><strong>原因：</strong> 这个组件库 2026 年把包名换成了 <code>@wot-ui/ui</code>。<strong>AI 的训练数据里旧名字的语料更多</strong>，它会自然地给出旧的那个。<strong>旧包在 npm 上依然存在（停在 1.14.0），所以照着装也能装上</strong> —— 不会报错，只是用的是一个不再更新的版本。</p><p><strong>怎么处理：</strong> 两个办法。</p><p><strong>一是在提示词里点名</strong>（上面模板一的做法）。<strong>二是养成核实包名的习惯</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查包存不存在、最新版本是多少</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/@wot-ui%2Fui/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 对照旧包名，看它停在哪个版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/wot-design-uni/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span></code></pre></div><p><strong>第二条命令更有价值</strong> —— 看到旧包版本号停在一年前、而新包还在持续更新，就知道该用哪个了。</p><details class="details custom-block"><summary>官方文档里的路径也要注意</summary><p>组件库的官方文档默认按 <code>uni_modules</code> 安装方式写例子，导入路径是 <code>@/uni_modules/wot-ui</code>。<strong>你的项目是 npm 安装的，路径是 <code>@wot-ui/ui</code>。</strong></p><p>照抄文档例子会报“找不到模块”，这不是 AI 的错，也不是文档的错，是安装方式不同。<strong>看到这个路径就手动换掉。</strong></p></details><h3 id="把-web-的-api-写进来" tabindex="-1">把 Web 的 API 写进来 <a class="header-anchor" href="#把-web-的-api-写进来" aria-label="Permalink to &quot;把 Web 的 API 写进来&quot;">​</a></h3><p><strong>现象：</strong> 代码里出现 <code>window.localStorage.setItem(...)</code>、<code>document.querySelector(...)</code>、<code>axios.get(...)</code>、<code>new FormData()</code>。</p><p><strong>原因：</strong> AI 见过的 Web 代码远多于跨端代码，这些是它的默认写法。<strong>H5 端这些全都能跑，所以你不容易发现。</strong></p><p><strong>怎么处理：</strong> 记住这张替换表，审查时逐条对照：</p><table tabindex="0"><thead><tr><th>AI 会写的</th><th>换成什么</th></tr></thead><tbody><tr><td><code>window.localStorage</code></td><td><code>uni.setStorageSync</code> / <code>uni.getStorageSync</code></td></tr><tr><td><code>document.querySelector</code></td><td>用 <code>ref</code> 拿组件实例，或者 <code>uni.createSelectorQuery</code></td></tr><tr><td><code>axios</code></td><td>项目封装好的 <code>http</code></td></tr><tr><td><code>new FormData()</code></td><td><code>uni.uploadFile</code></td></tr><tr><td><code>window.location.href</code></td><td><code>uni.navigateTo</code> / <code>uni.switchTab</code></td></tr><tr><td><code>fetch</code></td><td><code>uni.request</code></td></tr><tr><td><code>alert</code> / <code>confirm</code></td><td><code>uni.showToast</code> / <code>uni.showModal</code></td></tr><tr><td><code>window.setTimeout</code></td><td>直接用 <code>setTimeout</code>（这个能用）</td></tr></tbody></table><p><strong>最后一行说明不是所有 Web API 都不能用</strong> —— <code>setTimeout</code>、<code>Promise</code>、<code>Math</code>、<code>Date</code> 这些语言层面的东西在哪个端都有。<strong>要用条件编译或者换 API 的，是那些依赖浏览器环境的对象。</strong></p><h3 id="用-vue-router-的写法做跳转" tabindex="-1">用 vue-router 的写法做跳转 <a class="header-anchor" href="#用-vue-router-的写法做跳转" aria-label="Permalink to &quot;用 vue-router 的写法做跳转&quot;">​</a></h3><p><strong>现象：</strong> 代码里有 <code>router.push(&#39;/activity/1&#39;)</code>、<code>useRouter()</code>、<code>&lt;router-link&gt;</code>。</p><p><strong>原因：</strong> AI 把 Vue 生态的路由习惯直接套过来了。<strong>用户端根本没有 vue-router</strong>，路由是 <code>pages.json</code> 配置加 <code>uni.navigateTo</code> 这套。</p><p><strong>怎么处理：</strong> 换成 uni 的 API，并且<strong>注意 tabBar 页面的区别</strong>：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✗ AI 常写的</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">router.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/pages/activity/detail?id=&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✓ 换成 uni 的 API</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uni.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">navigateTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ url: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/pages/activity/detail?id=&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id })</span></span></code></pre></div><p><strong>特别要检查 <code>switchTab</code>。</strong> AI 即使知道用 <code>uni.navigateTo</code>，也常常对 tabBar 页面用错 —— 而这类错误<strong>只在真正点到那个按钮时才暴露</strong>，编译和构建都不报错。</p><h3 id="生命周期钩子从-vue-导入" tabindex="-1">生命周期钩子从 vue 导入 <a class="header-anchor" href="#生命周期钩子从-vue-导入" aria-label="Permalink to &quot;生命周期钩子从 vue 导入&quot;">​</a></h3><p><strong>现象：</strong> 代码写的是 <code>import { onLoad, onShow } from &#39;vue&#39;</code>，或者干脆用了 <code>onMounted</code> 来接收路由参数。</p><p><strong>原因：</strong> 在 Vue 3 Web 项目里，所有钩子都从 <code>vue</code> 导入。<strong>AI 会延续这个习惯</strong>，而 uni-app 的页面钩子来自另一个包。</p><p><strong>怎么处理：</strong> 分清两套钩子的来源：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✓ 页面级钩子：从 @dcloudio/uni-app 导入</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { onLoad, onShow, onPullDownRefresh, onReachBottom } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@dcloudio/uni-app&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✓ 组件级钩子：从 vue 导入</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { onMounted, onUnmounted, ref, computed } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue&#39;</span></span></code></pre></div><p><strong>从 <code>vue</code> 导入 <code>onLoad</code> 不会报错</strong>，它只是一个普通的导出（<code>undefined</code>），调用时会报“不是一个函数”，但这个报错出现的位置和真正的问题隔了很远。</p><h3 id="新加了页面但不改-pages-json" tabindex="-1">新加了页面但不改 pages.json <a class="header-anchor" href="#新加了页面但不改-pages-json" aria-label="Permalink to &quot;新加了页面但不改 pages.json&quot;">​</a></h3><p><strong>现象：</strong> AI 给了你一个完整的新页面 <code>.vue</code> 文件，你放进 <code>src/pages/</code>，跳转时报“页面不存在”。</p><p><strong>原因：</strong> 在 Web 项目里，新建一个组件文件就完事了；<strong>在 uni-app 里页面必须在 <code>pages.json</code> 里登记。</strong> AI 生成单文件时经常漏掉这一步。</p><p><strong>怎么处理：</strong> 每次让 AI 新增页面，<strong>在提示词里明确要求它同时给出 <code>pages.json</code> 要加的那一段</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新建页面时，除了给出 .vue 文件，还要给出 pages.json 里需要添加的配置片段，</span></span>
<span class="line"><span>包括 path、style 里的标题，以及如果这个页面在 tabBar 里，说明该用哪个跳转 API。</span></span></code></pre></div><p><strong>这个习惯能省掉一类反复出现的小麻烦。</strong></p><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><ul><li>[ ] <strong>两个端都跑过一遍</strong>了吗？H5 通过不算通过</li><li>[ ] 代码里有没有 <code>window</code> / <code>document</code> / <code>localStorage</code> / <code>axios</code> 这四个词</li><li>[ ] 有没有出现 <code>router.push</code> / <code>useRouter</code> / <code>router-link</code></li><li>[ ] 生命周期钩子的导入来源对不对（页面钩子来自 <code>@dcloudio/uni-app</code>）</li><li>[ ] 新增的页面，<code>pages.json</code> 里登记了吗</li><li>[ ] 涉及跳转的地方，跳的是不是 tabBar 页面，用的是 <code>switchTab</code> 吗</li><li>[ ] 请求有没有走项目封装好的 <code>http</code>，有没有自己拼 <code>uni.request</code></li><li>[ ] 用到的组件名能不能在你装的组件库版本里找到（<code>wd-</code> 开头的去 <code>node_modules/@wot-ui/ui/components/</code> 下看一眼）</li><li>[ ] 时间处理有没有直接用 <code>new Date(后端字符串)</code>（iOS 会挂）</li><li>[ ] <code>rpx</code> 和 <code>px</code> 的使用场合对不对（细线用了 px 吗）</li></ul><p><strong>这十条里，第 1 条和第 2 条能拦住大部分问题。</strong> 剩下的按出现频率排：跳转方式、生命周期导入、pages.json 漏登记。</p><p><strong>最后那两条（时间处理和 rpx）不是 AI 特有的问题</strong>，但因为它生成的代码量比你手写大得多，<strong>这类小问题的出现次数会被放大。</strong></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><p><strong>让 AI 写一个用户端的活动详情页，然后找出它写错的地方，改对并记录。</strong></p><p>任务要求：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>提示词</td><td>用本篇模板一的结构，包含三条“先确认”和四条约束</td></tr><tr><td>产出</td><td>一个完整可跑的详情页 <code>.vue</code> 文件</td></tr><tr><td>排查</td><td>逐条对照上面那份验收清单，记录发现的每一处问题</td></tr><tr><td>修改</td><td>每处问题都要在两个端验证过</td></tr><tr><td>记录</td><td>按下表格式写一份记录</td></tr></tbody></table><table tabindex="0"><thead><tr><th>序号</th><th>AI 写了什么</th><th>为什么不行</th><th>怎么改</th><th>在哪一端暴露的</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>验收标准：</strong></p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>记录条数</td><td>不少于 4 条</td></tr><tr><td>覆盖类型</td><td>至少包含：Web API、跳转方式、生命周期导入、pages.json 这四类各一条</td></tr><tr><td>暴露端</td><td>每条都要写清是在哪一端、什么操作下暴露的</td></tr><tr><td>两个端</td><td>修改后的代码在两个端都验证过</td></tr><tr><td>结论</td><td>最后写两三句：哪类问题最容易漏，为什么</td></tr></tbody></table><p><strong>不合格的记录：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 1 | 用了 localStorage | 小程序不支持 | 改成 uni.setStorageSync | 小程序 |</span></span></code></pre></div><p><strong>只写“不支持”等于没记录。</strong> 要说清是哪一步暴露的 —— 是编译时报错，还是运行时白屏，还是点到某个按钮才出问题。<strong>这决定了你今后在哪个阶段检查它。</strong></p><p><strong>合格的记录：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 1 | window.localStorage.setItem(&#39;token&#39;, ...) | 小程序没有 window 对象 | 换成 uni.setStorageSync(&#39;token&#39;, ...) | H5 端完全正常；小程序端编译不报错，进页面时白屏，控制台报 window is not defined |</span></span>
<span class="line"><span>| 2 | router.push(&#39;/pages/signup/form?id=&#39; + id) | 用户端没有 vue-router | 换成 uni.navigateTo | 编译期就报错，这一条好发现 |</span></span>
<span class="line"><span>| 3 | import { onLoad, onShow } from &#39;vue&#39; | 页面钩子要从 @dcloudio/uni-app 导入 | 拆成两行导入 | 编译不报错，进页面时 onLoad 不是函数，整个页面逻辑不执行 |</span></span>
<span class="line"><span>| 4 | 新页面没有登记到 pages.json | 没登记的页面跳不过去 | 补上 path 与 style | 点击跳转时提示页面不存在 |</span></span></code></pre></div><p><strong>参考思路：</strong></p><p>三个地方值得注意：</p><p><strong>一是“在哪一端暴露”这一列最有价值。</strong> 你会发现规律：<strong>编译期报错的问题都好解决</strong>（改完就过），<strong>运行时才暴露的才是麻烦的</strong>（第 1、3 条都是）。而第 3 条的报错位置和真实原因隔得很远 —— <strong>这类问题要多花时间定位，记录时把定位过程也写下来。</strong></p><p><strong>二是同一份提示词跑两次，比较两次的结果。</strong> 同一个 AI 两次给出的代码，错误位置不一定相同，<strong>但它容易犯哪几类错是稳定的。</strong> 摸清这个规律，比记住某一次的具体错误有用。</p><p><strong>三是把这份记录留下来。</strong> 答辩时可以放进“开发生成记录”里 —— 单元 11 的 AI 参与声明里有一栏是“发现的错误”，<strong>这种有现象、有原因、有改法的记录，比“用了 AI 提效”这种空话有说服力得多。</strong></p></details><hr><p>上一节：<a href="/frontend-engineering-course/mobile/09-publish.html">打包与发布</a> · 返回：<a href="/frontend-engineering-course/mobile/">用户端总览</a></p>`,62)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
